def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a datetime.timedelta instance
    :type value: datetime.timedelta
    :return: total seconds as int if no microseconds, else float; None if invalid input
    """
    if value is None:
        return None
    if not isinstance(value, timedelta):
        return None
    try:
        total = value.total_seconds()
    except Exception:
        return None
    if isinstance(total, float) and total.is_integer():
        return int(total)
    return total

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: time instance
    :type value: datetime.time
    :return: string representation of the time or None if value is None
    """
    if value is None:
        return None
    try:
        # Use strftime to format the time. Include microseconds only if present.
        if getattr(value, "microsecond", 0):
            # Format with microseconds and strip trailing zeros
            formatted = value.strftime("%H:%M:%S.%f")
            formatted = formatted.rstrip("0").rstrip(".")
            return formatted
        else:
            return value.strftime("%H:%M:%S")
    except AttributeError:
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

