    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a float or None")
        if timeout < 0:
            raise ValueError("timeout must not be negative")

    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            # Attach metadata if provided
            if metadata:
                try:
                    tx.set_metadata(metadata)
                except AttributeError:
                    raise AttributeError("Transaction object does not support set_metadata")
            # Set timeout if provided
            if timeout is not None:
                try:
                    tx.set_timeout(timeout)
                except AttributeError:
                    raise AttributeError("Transaction object does not support set_timeout")
            # Execute the wrapped function
            return func(tx, *args, **kwargs)
        return wrapper
    return decorator

