def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Guard against invalid inputs
    if not isinstance(observer_schema, list) or not isinstance(response, list):
        return

    # Ensure the manifest is a dict-like structure for field assignment
    if not isinstance(last_applied_manifest, dict):
        # If it's a list, we cannot assign by key; skip processing
        return

    for field in observer_schema:
        # Nested schema represented as a dict: {field_name: sub_schema}
        if isinstance(field, dict):
            for key, sub_schema in field.items():
                # Initialize the key if missing
                if key not in last_applied_manifest:
                    # Use the value from response if available, otherwise None
                    last_applied_manifest[key] = response[key] if key in response else None

                # Recurse into nested structures if present in response
                if key in response:
                    resp_val = response[key]
                else:
                    resp_val = None

                if isinstance(sub_schema, dict):
                    # Ensure nested dict exists
                    if not isinstance(last_applied_manifest[key], dict):
                        last_applied_manifest[key] = {}
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key], sub_schema, resp_val or {}
                    )
                elif isinstance(sub_schema, list):
                    # Ensure nested list exists
                    if not isinstance(last_applied_manifest[key], list):
                        last_applied_manifest[key] = []
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[key], sub_schema, resp_val or []
                    )
        else:
            # Simple field name
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field] if field in response else None
    # No explicit return; the manifest is modified in place.

def status_str(self, prefix=''):
