    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    # If status is an enum, use its name; otherwise convert to string
    status_text = status.name if hasattr(status, 'name') else str(status)
    return f"{prefix}{status_text}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Ensure prefix is a string
    try:
        prefix = str(prefix)
    except Exception:
        prefix = ''

    # Attempt to locate a log attribute
    log = None
    for attr in ('log', 'validation_log', 'entries', 'messages'):
        if hasattr(self, attr):
            log = getattr(self, attr)
            break

    if log is None:
        return prefix + "No log available."

    # Helper to convert an entry to string safely
    def entry_to_str(entry):
        try:
            return str(entry)
        except Exception:
            return repr(entry)

    # Build lines based on the type of log
    lines = []
    if isinstance(log, (list, tuple)):
        for entry in log:
            lines.append(prefix + entry_to_str(entry))
    elif isinstance(log, dict):
        for key, value in log.items():
            lines.append(prefix + f"{key}: {entry_to_str(value)}")
    elif isinstance(log, str):
        lines.append(prefix + log)
    else:
        # Fallback for any other iterable
        try:
            for entry in log:
                lines.append(prefix + entry_to_str(entry))
        except Exception:
            lines.append(prefix + entry_to_str(log))

    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if digests_used is None:
        raise ValueError("digests_used cannot be None")

    # Ensure digests_used is a set for efficient lookup
    if not isinstance(digests_used, set):
        digests_used = set(digests_used)

    manifest_digests = set()
    for entry in manifest_files:
        # Support dicts with a 'digest' key or tuples/lists where digest is the second element
        if isinstance(entry, dict):
            digest = entry.get('digest')
        else:
            try:
                digest = entry[1]
            except Exception:
                raise ValueError(f"Invalid manifest entry format: {entry}")

        if not digest:
            raise ValueError(f"Missing digest in manifest entry: {entry}")

        manifest_digests.add(digest)

    # Check that every digest in the manifest is present in the used set
    missing_in_used = manifest_digests - digests_used
    if missing_in_used:
        raise ValueError(f"Digests present in manifest but not used: {missing_in_used}")

    # Optionally, ensure that every used digest is actually listed in the manifest
    unused_in_manifest = digests_used - manifest_digests
    if unused_in_manifest:
        raise ValueError(f"Digests used but not present in manifest: {unused_in_manifest}")

    return None

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        return {}
    if version is None:
        raise ValueError("version must be provided")

    result = {}

    # Inventory can be a dict mapping logical_path -> list of entries
    # or a list/tuple of entry dicts.
    if isinstance(inventory, dict):
        for logical_path, entries in inventory.items():
            if not isinstance(entries, (list, tuple)):
                continue
            for entry in entries:
                try:
                    if entry.get("version") == version:
                        content_file = entry.get("content_file")
                        if content_file:
                            result.setdefault(logical_path, set()).add(content_file)
                except AttributeError:
                    continue
    elif isinstance(inventory, (list, tuple)):
        for entry in inventory:
            try:
                if (
                    entry.get("logical_path")
                    and entry.get("content_file")
                    and entry.get("version") == version
                ):
                    logical_path = entry["logical_path"]
                    content_file = entry["content_file"]
                    result.setdefault(logical_path, set()).add(content_file)
            except AttributeError:
                continue
    else:
        raise TypeError("inventory must be a dict or list of entries")

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if fixity is None:
        raise ValueError("Fixity block cannot be None")
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Accept either a single file entry under 'file' or a list under 'files'
    if 'files' in fixity:
        files = fixity['files']
    elif 'file' in fixity:
        files = [fixity['file']]
    else:
        raise ValueError("Fixity block must contain either 'files' or 'file' key")

    if not isinstance(files, list):
        raise ValueError("'files' (or 'file') must be a list of file entries")

    # Prepare a set for quick membership checks
    manifest_set = set(manifest_files or [])

    required_keys = {'path', 'hash', 'size'}
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")
        missing = required_keys - entry.keys()
        if missing:
            raise ValueError(f"File entry at index {idx} missing keys: {', '.join(sorted(missing))}")

        path = entry['path']
        if not isinstance(path, str):
            raise ValueError(f"File entry at index {idx} 'path' must be a string")
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block is not present in the manifest")

        hash_val = entry['hash']
        if not isinstance(hash_val, str):
            raise ValueError(f"File entry at index {idx} 'hash' must be a string")

        size_val = entry['size']
        if not isinstance(size_val, int):
            raise ValueError(f"File entry at index {idx} 'size' must be an integer")

    return True

def files_list(path):
    """Return the files in `path`"""
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        try:
            return [
                os.path.abspath(os.path.join(path, f))
                for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))
            ]
        except OSError as exc:
            raise exc
    raise ValueError(f"Unsupported path type: {path}")

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First collect all XML basenames
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_basenames.add(base)

            if not xml_basenames:
                return {}

            # Group files by those basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base = os.path.splitext(os.path.basename(name))[0]
                if base in xml_basenames:
                    if base not in result:
                        result[base] = {}
                    try:
                        content = zf.read(name)
                    except Exception:
                        content = None
                    result[base][name] = content
    except Exception:
        # If any error occurs (file not found, not a zip, etc.), return empty dict
        return {}
    return result

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    if zip_path is None:
        raise TypeError("zip_path must be provided")
    # Allow passing an already opened ZipFile object
    if isinstance(zip_path, zipfile.ZipFile):
        zf = zip_path
        close = False
    else:
        if not os.path.exists(zip_path):
            raise FileNotFoundError(f"Zip file {zip_path!r} does not exist")
        try:
            zf = zipfile.ZipFile(zip_path, "r")
        except zipfile.BadZipFile as exc:
            raise ValueError(f"File {zip_path!r} is not a valid zip archive") from exc
        close = True
    try:
        # Return all non-directory entries
        return [name for name in zf.namelist() if not name.endswith("/") and not name.endswith(".pyc")]
    finally:
        if close:
            zf.close()

