def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            result = namefunc(*args, **kwargs)
            # In Python 2, ensure the result is a byte string
            if isinstance(result, six.text_type):
                return result.encode()
            return result
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"

    # Attempt to read a VERSION file in the current directory
    try:
        with open("VERSION", "r") as f:
            return f.read().strip()
    except Exception:
        pass

    # Attempt to use importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version as get_version, PackageNotFoundError
        pkg_name = __package__ or __name__
        return get_version(pkg_name)
    except Exception:
        pass

    # Fallback to pkg_resources for older Python versions
    try:
        import pkg_resources
        pkg_name = __package__ or __name__
        return pkg_resources.get_distribution(pkg_name).version
    except Exception:
        pass

    return default

