def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        return ""
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    width = len(version)
    try:
        num = int(version)
    except ValueError:
        raise ValueError("invalid numeric version")
    num += 1
    new_width = max(width, len(str(num)))
    return str(num).zfill(new_width)

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None or not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if bug_ids is None:
        return params
    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, (int, str)):
        bug_ids_list = [str(bug_ids)]
    else:
        try:
            bug_ids_list = [str(b) for b in bug_ids]
        except TypeError:
            raise ValueError("bug_ids must be an int, str, or an iterable of ints/strs")
    # Merge with any existing 'ids' entry
    existing = params.get('ids')
    if existing:
        if isinstance(existing, list):
            existing_list = [str(e) for e in existing]
        else:
            existing_list = [e.strip() for e in str(existing).split(',') if e.strip()]
        combined = existing_list + bug_ids_list
    else:
        combined = bug_ids_list
    # Store as a comma‑separated string as Bugzilla expects
    params['ids'] = ','.join(combined)
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping(node):
        """Return True if node is a MappingNode (tag ends with ':map')."""
        return getattr(node, 'tag', '').endswith(':map')

    def merge_mapping_nodes(target, source):
        """
        Merge source MappingNode into target MappingNode in place.
        Both target and source are assumed to be mapping nodes.
        """
        # Build a lookup from key value to index in target.value
        target_map = {}
        for idx, (k_node, v_node) in enumerate(target.value):
            target_map[k_node.value] = idx

        for s_k_node, s_v_node in source.value:
            key = s_k_node.value
            if key in target_map:
                t_idx = target_map[key]
                t_k_node, t_v_node = target.value[t_idx]
                if is_mapping(t_v_node) and is_mapping(s_v_node):
                    merge_mapping_nodes(t_v_node, s_v_node)
                else:
                    # Replace with source value (last wins)
                    target.value[t_idx] = (t_k_node, s_v_node)
            else:
                # Append new key/value pair
                target.value.append((s_k_node, s_v_node))
                target_map[key] = len(target.value) - 1

    result = []
    key_index = {}
    for k_node, v_node in nodes:
        key = getattr(k_node, 'value', None)
        if key is None:
            # If key node doesn't have a value attribute, treat as unique
            result.append((k_node, v_node))
            continue
        if key not in key_index:
            result.append((k_node, v_node))
            key_index[key] = len(result) - 1
        else:
            idx = key_index[key]
            existing_k, existing_v = result[idx]
            if is_mapping(existing_v) and is_mapping(v_node):
                merge_mapping_nodes(existing_v, v_node)
            else:
                # Replace with the new value (last wins)
                result[idx] = (existing_k, v_node)
    return result

