def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping_node(node):
        # A MappingNode has a 'value' attribute that is a list of key/value tuples
        return hasattr(node, 'value') and isinstance(node.value, list)

    def merge_mapping_nodes(m1, m2):
        # Combine the key/value lists from both mapping nodes and deep merge
        combined = m1.value + m2.value
        merged_list = deep_merge_nodes(combined)
        # Preserve the tag from the first mapping node
        return type(m1)(tag=m1.tag, value=merged_list)

    merged = {}
    for k_node, v_node in nodes:
        key = getattr(k_node, 'value', None)
        if key is None:
            # If key node doesn't have a 'value', skip or treat as unique
            merged[id(k_node)] = (k_node, v_node)
            continue
        if key not in merged:
            merged[key] = (k_node, v_node)
        else:
            existing_k, existing_v = merged[key]
            if is_mapping_node(existing_v) and is_mapping_node(v_node):
                merged_value = merge_mapping_nodes(existing_v, v_node)
                merged[key] = (existing_k, merged_value)
            else:
                # Last value wins; keep the key node from the first occurrence
                merged[key] = (existing_k, v_node)
    return list(merged.values())

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    import sys

    parser = argparse.ArgumentParser(description='Parse command line arguments')
    # Flatten arguments if a single list/tuple is provided
    if len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
        args = arguments[0]
    else:
        args = arguments

    try:
        return parser.parse_args(args)
    except SystemExit as exc:
        # argparse uses SystemExit to signal parsing errors; convert to ValueError
        raise ValueError(f"Argument parsing failed: {exc}") from exc
    except Exception as exc:
        raise ValueError(f"Error parsing arguments: {exc}") from exc

