def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")
    return (response[i:i + max_results] for i in range(0, len(response), max_results))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as e:
                    raise TypeError(f"Cannot add values for key '{key}': {e}") from e
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only strings can represent a None value
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string is considered a None representation
        if not stripped:
            return True
        # Common textual representations of None
        if stripped.lower() in ("none", "null"):
            return True
    return False

