def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subs = current.__subclasses__()
        except Exception:
            continue
        for sub in subs:
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError("string must be a str")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of single-character strings")

    # Alphabet must contain at least two unique characters for a valid base
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two unique characters to represent a base >= 2")

    # Ensure all alphabet elements are single-character strings and unique
    seen = set()
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError("alphabet elements must be single-character strings")
        if ch in seen:
            raise ValueError("alphabet must contain unique characters")
        seen.add(ch)

    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    # Convert the string to an integer
    n = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' not found in alphabet")
        n = n * base + char_to_value[ch]

    return n

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import os
    import tarfile
    import tempfile
    from pathlib import Path
    import requests

    # Ensure destination_path is a Path instance
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)

    # Create destination directory if it does not exist
    try:
        if destination_path.exists():
            # If directory exists but is not empty, raise an error
            if destination_path.is_dir() and any(destination_path.iterdir()):
                raise OSError(f"Destination directory '{destination_path}' already exists and is not empty.")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Failed to prepare destination directory '{destination_path}': {exc}") from exc

    # Download the archive to a temporary file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(f"Failed to download archive from '{url}': {exc}") from exc

    temp_file = None
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp:
            temp_file = Path(tmp.name)
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp.write(chunk)
    except Exception as exc:
        if temp_file and temp_file.exists():
            temp_file.unlink(missing_ok=True)
        raise RuntimeError(f"Failed to write temporary archive file: {exc}") from exc

    # Extract the archive
    try:
        with tarfile.open(temp_file, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except tarfile.TarError as exc:
        raise RuntimeError(f"Failed to extract archive '{temp_file}': {exc}") from exc
    finally:
        # Clean up the temporary file
        if temp_file and temp_file.exists():
            try:
                temp_file.unlink()
            except Exception:
                pass

    return destination_path

def os_is_mac():
