def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    result = {}
    for key, value in item.items():
        # Only convert string keys that contain wildcard characters
        if isinstance(key, str) and ('*' in key or '?' in key):
            # Build regex pattern
            pattern_parts = []
            for ch in key:
                if ch == '*':
                    pattern_parts.append('.*')
                elif ch == '?':
                    pattern_parts.append('.')
                elif ch in ".^$+{}[]|()":
                    pattern_parts.append('\\' + ch)
                else:
                    pattern_parts.append(ch)
            pattern = '^' + ''.join(pattern_parts) + '$'
            result[pattern] = value
        else:
            # Keep key unchanged
            result[key] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    if len(name) > 1:
        first, last = name[0], name[-1]
        if first == last and first in ('"', "'", "`"):
            return name[1:-1]
    return name

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.stderr}") from e

    files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in infos:
        sockaddr = info[4]
        addr = sockaddr[0]
        try:
            import ipaddress
            if ipaddress.ip_address(addr).is_loopback:
                return True
        except Exception:
            continue
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    if not config_filename:
        raise ValueError("config_filename must be provided")
    if rendered_config is None:
        raise ValueError("rendered_config must be provided")
    config_path = os.path.expanduser(config_filename)
    if os.path.isfile(config_path) and not overwrite:
        return
    dir_name = os.path.dirname(config_path)
    if dir_name:
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as e:
            if not os.path.isdir(dir_name):
                raise
    try:
        with open(config_path, 'w') as f:
            f.write(rendered_config)
        os.chmod(config_path, mode)
    except OSError as e:
        raise OSError(f"Failed to write configuration to {config_path}: {e}") from e

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from matcher
