def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    try:
        yaml_str = yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping object to YAML: {exc}") from exc
    # In Python 2, yaml.safe_dump returns a byte string; convert to unicode.
    if isinstance(yaml_str, bytes):
        try:
            yaml_str = yaml_str.decode("utf-8")
        except Exception:
            yaml_str = yaml_str.decode("latin1")
    return yaml_str

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import toml
    except ImportError:
        toml = None
    try:
        import yaml
    except ImportError:
        yaml = None

    def _resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_in_obj(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_in_obj(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    configs = {}
    error_records = []

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            ext = os.path.splitext(filename)[1].lower()
            parsed = None
            if ext == '.toml':
                if toml is None:
                    raise ImportError("toml module not available")
                parsed = toml.loads(content)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError("yaml module not available")
                parsed = yaml.safe_load(content)
            elif ext == '.json':
                parsed = json.loads(content)
            else:
                # Try yaml as fallback
                if yaml is None:
                    raise ImportError("yaml module not available for fallback parsing")
                parsed = yaml.safe_load(content)
            if not isinstance(parsed, dict):
                raise ValueError(f"Parsed configuration is not a dictionary: {type(parsed)}")
            if overrides:
                parsed.update(overrides)
            if resolve_env:
                parsed = _resolve_env_in_obj(parsed)
            configs[filename] = parsed
        except Exception as exc:
            record = logging.LogRecord(
                name=filename,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=exc
            )
            error_records.append(record)

    return configs, error_records

def force_string(obj):
