        except UnicodeEncodeError as e:
            raise ValueError(f"Unable to encode string to UTF-8: {e}") from e
    return obj

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise TypeError("values must be an iterable of strings")
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, not a single string")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")
    bookmarks = []
    for raw in iterator:
        if not isinstance(raw, str):
            raise TypeError(f"bookmark value must be a string, got {type(raw).__name__}")
        try:
            # Prefer a dedicated parser if available
            if hasattr(Bookmark, "from_raw_value"):
                bookmark = Bookmark.from_raw_value(raw)
            else:
                bookmark = Bookmark(raw)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark from raw value: {raw!r}") from exc
        bookmarks.append(bookmark)
    # Attempt to construct the Bookmarks instance; fall back to keyword if needed
    try:
        return cls(bookmarks)
    except TypeError:
        return cls(bookmarks=bookmarks)

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if default is __marker:
        # No default provided; let super().pop raise KeyError if key missing
        return super().pop(key)
    else:
        # Default provided; return it if key missing
        return super().pop(key, default)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Ensure the cache has the expected internal structures
    if not hasattr(self, "_order") or not hasattr(self, "_cache"):
        raise AttributeError("LRU cache internal structures missing")

    # Attempt to retrieve the least‑recently used key
    try:
        # Common case: _order is a list or deque
        key = self._order.pop(0)
    except IndexError:
        # The cache is empty
        raise KeyError("LRU cache is empty")
    except Exception:
        # Fallback: _order might be an OrderedDict or similar
        try:
            key, _ = self._order.popitem(last=False)
        except Exception:
            raise KeyError("Unable to determine least recently used item")

    # Remove the key from the underlying cache
    try:
        value = self._cache.pop(key)
    except KeyError:
        # Inconsistent state: key not present in cache
        raise KeyError(f"Key {key!r} not found in cache")

    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = dict.popitem(self)
        return key, value
    except KeyError:
        raise KeyError('dict is empty')

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dictionary is empty')
    import random
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

