def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    import json
    import xml.etree.ElementTree as etree

    # Helper to get body as string
    body = request.body
    if isinstance(body, bytes):
        try:
            body_str = body.decode("utf-8", errors="ignore")
        except Exception:
            body_str = ""
    else:
        body_str = str(body)

    # Try JSON payload (private message)
    try:
        data = json.loads(body_str)
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Try XML payload (public message)
    try:
        xml = etree.fromstring(body_str.encode("utf-8", errors="ignore"))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    # Legacy payload check (optional, can be customized)
    # Example: legacy payload might contain a specific string or structure
    # Here we simply check for a known legacy marker if defined
    try:
        if hasattr(request, "legacy_marker") and request.legacy_marker in body_str:
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Attempt to determine the request path
        path = None
        if hasattr(request, "path"):
            path = request.path
        elif hasattr(request, "META"):
            path = request.META.get("PATH_INFO")
        elif hasattr(request, "get_full_path"):
            path = request.get_full_path()

        if path and path.startswith("/_matrix/"):
            return True

        # Fallback: check content type for typical Matrix JSON payloads
        content_type = None
        if hasattr(request, "META"):
            content_type = request.META.get("CONTENT_TYPE")
        elif hasattr(request, "headers"):
            content_type = request.headers.get("Content-Type")

        if content_type and content_type.startswith("application/json"):
            return True

        return False
    except Exception:
        # In case of any unexpected attribute access or other errors, assume not a Matrix request
        return False

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return ''
    import re
    # Regex to match URLs starting with http://, https://, or www.
    url_pattern = re.compile(r'\b((?:https?://|www\.)[^\s<]+[^\s<\.\,])', re.IGNORECASE)

    def _replace(match):
        url = match.group(1)
        href = url
        if url.lower().startswith('www.'):
            href = 'http://' + url
        # Escape double quotes in href if any (unlikely but safe)
        href_escaped = href.replace('"', '&quot;')
        return f'<a href="{href_escaped}" target="_blank" rel="noopener noreferrer">{url}</a>'

    try:
        return url_pattern.sub(_replace, text)
    except Exception:
        # In case of any unexpected error, return the original text unchanged
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme not in ("http", "https"):
            return None
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.getheader("Content-Type")
    except urllib.error.HTTPError as e:
        # Even on HTTP errors we may still get headers
        return e.headers.get("Content-Type")
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        if len(tag) > 30:
            return False
        import re
        pattern = re.compile(r'^[A-Za-z0-9_.-]+$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # If an ElementTree, get its root element
    if hasattr(node, 'getroot'):
        node = node.getroot()
    # Ensure node is iterable (Element or ElementTree)
    try:
        iter(node)
    except TypeError:
        raise TypeError("Expected an ElementTree Element or ElementTree, got %r" % (node,))
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")
    base = url.rstrip("/")  # remove any trailing slash

    # Determine the NodeInfo document path
    if document_path is None:
        path = "/.well-known/nodeinfo/1.0"
    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        # Ensure the path starts with a slash
        path = document_path if document_path.startswith("/") else "/" + document_path

    href = base + path

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        return None
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        subject = data.get("subject")
        links = {}
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links[rel] = href
        return {"subject": subject, "links": links}
    except Exception:
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            # Extract subject
            subject = None
            for elem in root.iter():
                if elem.tag.endswith("Subject"):
                    subject = elem.text
                    break
            # Extract links
            links = {}
            for elem in root.iter():
                if elem.tag.endswith("Link"):
                    rel = elem.attrib.get("rel")
                    href = elem.attrib.get("href")
                    if rel and href:
                        links[rel] = href
            return {"subject": subject, "links": links}
        except Exception:
            return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Ensure the handle is in the form user@example.com
        if "@" not in handle:
            return None
        # Build the resource parameter
        resource = handle if handle.startswith("acct:") else f"acct:{handle}"
        host = handle.split("@")[1]
        url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource)}"
    except Exception:
        return None

    try:
        with urllib.request.urlopen(url) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode("utf-8")
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None

    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)

    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None

    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link or not lrdd_link.template:
        return None

    url = lrdd_link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception or not document:
        return None

    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        return None
    try:
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    except Exception:
        return None
    if exception or not document:
        return None
    try:
        xrd = XRD.parse_xrd(document)
    except Exception:
        return None
    return xrd

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key is None:
        raise ValueError("key cannot be None")
    current = dic
    all_keys = [key] + list(keys)
    for i, k in enumerate(all_keys):
        # ensure key is hashable
        try:
            hash(k)
        except TypeError:
            raise TypeError(f"key {k!r} is not hashable")
        if i == len(all_keys) - 1:
            current[k] = val
        else:
            if k not in current or not isinstance(current[k], dict):
                if k in current and not isinstance(current[k], dict):
                    raise TypeError(f"intermediate key {k!r} is not a dict")
                current[k] = {}
            current = current[k]
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)

        matched_files = []

        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                # Skip directories
                full_path = os.path.join(directory, fname)
                if os.path.isdir(full_path):
                    continue

                # Apply spec_option filter
                if spec_option:
                    if isinstance(spec_option, str):
                        # Treat as glob pattern
                        if not fnmatch.fnmatch(fname, spec_option):
                            continue
                    elif callable(spec_option):
                        # Use callable to decide
                        try:
                            if not spec_option(fname):
                                continue
                        except Exception:
                            continue
                    else:
                        # Unsupported spec_option type; skip
                        continue

                matched_files.append(full_path)

        return sorted(matched_files)
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

