@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")

    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML content: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping (dictionary)")

    # Define the required top‑level fields for a valid spec.
    # Adjust this list to match the actual specification requirements.
    required_fields = ["name", "type", "spec"]
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as fnf:
            raise IRValidatorException(f"File not found: {yaml_file}") from fnf
        except yaml.YAMLError as ye:
            raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {ye}") from ye
        except Exception as e:
            raise IRValidatorException(f"Unexpected error reading {yaml_file}: {e}") from e

        if data is None:
            raise IRValidatorException(f"YAML file {yaml_file} is empty or contains no data")

        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file {yaml_file} must contain a mapping at the top level")

        # Define mandatory fields that must be present in the YAML data
        mandatory_fields = ["type"]
        missing_fields = [field for field in mandatory_fields if field not in data]
        if missing_fields:
            raise IRValidatorException(
                f"Missing required fields in {yaml_file}: {', '.join(missing_fields)}"
            )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import os
    try:
        import yaml
    except ImportError:
        yaml = None
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")
    visited = set()
    def _resolve(d, base_dir):
        include = d.pop('include', None)
        if include is None:
            return
        if not isinstance(include, dict):
            raise ValueError("include directive must be a dict")
        for key, rel_path in include.items():
            abs_path = os.path.abspath(os.path.join(base_dir, rel_path))
            if abs_path in visited:
                raise RuntimeError(f"Circular include detected: {abs_path}")
            visited.add(abs_path)
            if not os.path.isfile(abs_path):
                raise FileNotFoundError(f"Included spec file not found: {abs_path}")
            with open(abs_path, 'r') as f:
                if yaml:
                    try:
