def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Start with defaults defined on the arguments themselves
    for arg in getattr(self, 'args', []):
        try:
            # Skip arguments that do not have a default or are marked as NoDefault
            if hasattr(arg, 'default') and arg.default is not None:
                defaults[arg.name] = arg.default
        except Exception:
            # If any attribute access fails, ignore this argument
            continue

    # Merge defaults from the base spec if present
    base_spec = getattr(self, '_default_spec', None)
    if base_spec is not None:
        try:
            if isinstance(base_spec, dict):
                defaults.update(base_spec)
            else:
                defaults.update(vars(base_spec))
        except Exception:
            # If the base spec cannot be converted to a dict, ignore it
            pass

    # Finally, merge defaults from the overridden spec (highest priority)
    spec = getattr(self, 'spec', None)
    if spec is not None:
        try:
            if isinstance(spec, dict):
                defaults.update(spec)
            else:
                defaults.update(vars(spec))
        except Exception:
            # If the spec cannot be converted to a dict, ignore it
            pass

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    # Retrieve the internal mapping of command names to option specs.
    # Prefer a private attribute, fall back to a public one if necessary.
    options_map = getattr(self, "_command_options", None)
    if options_map is None:
        options_map = getattr(self, "command_options", {})
    if not isinstance(options_map, dict):
        # If the attribute exists but is not a dict, treat as empty mapping.
        options_map = {}
    # Attempt a direct lookup.
    opts = options_map.get(command_name)
    # If not found, try a case‑insensitive match.
    if opts is None:
        for key, val in options_map.items():
            if isinstance(key, str) and key.lower() == command_name.lower():
                opts = val
                break
    # If still not found, return an empty list.
    if opts is None:
        return []
    # Ensure the result is a list; if a single spec is stored, wrap it.
    if isinstance(opts, (list, tuple)):
        return list(opts)
    return [opts]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")

    # Ensure the specification container exists
    if not hasattr(self, "_specs"):
        raise AttributeError("The object does not contain a '_specs' attribute")

    # Retrieve the command's specification dictionary
    try:
        command_spec = self._specs[command_name]
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found in specifications")

    # Retrieve the specific option's specification
    try:
        return command_spec[argument_name]
    except KeyError:
        raise KeyError(f"Argument '{argument_name}' not found for command '{command_name}'")

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if args is None:
        return []
    silent = []
    try:
        for arg in args:
            if isinstance(arg, str) and arg.startswith('-'):
                silent.append(arg.lstrip('-'))
    except TypeError:
        raise TypeError("args must be an iterable of strings")
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")

    # Retrieve the list of required argument names
    if not hasattr(self, "required_args"):
        raise AttributeError("Instance has no 'required_args' attribute")
    required = getattr(self, "required_args")

    # Validate that required is an iterable of names
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("'required_args' must be an iterable of argument names")

    # Find any missing or None-valued required arguments
    missing = [name for name in required if name not in args or args[name] is None]

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    if not options_spec:
        return required

    for opt in options_spec:
        # Extract the option name; support dict or object with attribute
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or cond is None:
            continue

        matched = False
        try:
            if callable(cond):
                matched = bool(cond(args, command_name))
            elif isinstance(cond, str):
                # Evaluate the string expression in a safe namespace
                matched = bool(eval(cond, {}, {'args': args, 'command_name': command_name}))
            else:
                # Unsupported condition type; skip
                continue
        except Exception:
            # If evaluation fails, treat as not matched
            continue

        if matched:
            required.append(name)

    return required

