def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of (value, min, max) tuples")

    for idx, item in enumerate(iterator):
        # Each item must be a tuple/list of length 3
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise TypeError(f"Argument at index {idx} must be a tuple of (value, min, max)")
        value, min_, max_ = item

        # Skip validation if value is None
        if value is None:
            continue

        # Validate against minimum
        if min_ is not None and value < min_:
            raise ValueError(
                f"Argument {idx} value {value} is less than the minimum {min_}"
            )

        # Validate against maximum
        if max_ is not None and value > max_:
            raise ValueError(
                f"Argument {idx} value {value} is greater than the maximum {max_}"
            )

    return args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (tuple, list)) and len(item) == 2:
                key, value = item
                vars_dict[key] = value
            else:
                # Unsupported item type; ignore or raise if desired
                pass
    else:
        raise TypeError("extra_vars must be a dict or list")
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Validate playbook path
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    command = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("verbose must be non-negative")
            command.append("-" + "v" * verbose)
        elif isinstance(verbose, str):
            command.append(verbose)
        else:
            raise TypeError("verbose must be an int or str")

    # Handle ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            flag = key if key.startswith("--") else f"--{key}"
            if isinstance(value, bool):
                if value:
                    command.append(flag)
                # skip if False
            elif isinstance(value, (list, tuple)):
                if not value:
                    continue
                command.append(flag)
                command.append(",".join(map(str, value)))
            else:
                command.append(flag)
                command.append(str(value))

    # Handle extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except (TypeError, ValueError) as e:
            raise ValueError(f"extra_vars must be JSON serializable: {e}")
        command.extend(["--extra-vars", json_str])

    # Execute the command
    try:
        result = subprocess.run(command, capture_output=True, text=True, check=False)
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible playbook failed with exit code {result.returncode}:\n{result.stderr}"
        )

    return result.stdout

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Determine spec file (prefer JSON, fallback to YAML)
    spec_path = None
    json_path = os.path.join(plugin_dir, "plugin.json")
    yaml_path = os.path.join(plugin_dir, "plugin.yaml")
    if os.path.isfile(json_path):
        spec_path = json_path
    elif os.path.isfile(yaml_path):
        spec_path = yaml_path
    else:
        raise FileNotFoundError("No plugin spec file found (plugin.json or plugin.yaml)")

    # Load spec
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith('.json'):
                spec_data = json.load(f)
            else:
                try:
                    import yaml
                    spec_data = yaml.safe_load(f)
                except Exception as e:
                    raise ValueError(f"Failed to parse YAML spec: {e}")
    except Exception as e:
        raise ValueError(f"Error reading spec file: {e}")

    if not isinstance(spec_data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Flatten and return
    return _flatten(spec_data)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        return path
    abs_root = os.path.abspath(root)
    abs_path = os.path.abspath(path)
    if not abs_path.startswith(abs_root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    stripped = abs_path[len(abs_root):]
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]
    return stripped
